#!/usr/bin/env bash
# Writes Casks/kudzu.rb into a checkout of Stringsaeed/homebrew-tap.
# Usage: update-cask.sh <version> <dmg-sha256> <tap-dir>
set -euo pipefail
VERSION=$1 SHA=$2 TAP=$3
[[ $VERSION =~ ^[0-9]+\.[0-9]+\.[0-9]+$ && $SHA =~ ^[a-fA-F0-9]{64}$ ]] || { echo 'invalid stable version or SHA256' >&2; exit 1; }
mkdir -p "$TAP/Casks"
cat > "$TAP/Casks/kudzu.rb" <<CASK
# Generated by Kudzu's release workflow (apps/desktop-v2/scripts/release/update-cask.sh). Don't edit by hand.
cask "kudzu" do
  version "$VERSION"
  sha256 "$SHA"

  url "https://github.com/Stringsaeed/kudzu/releases/download/v#{version}/Kudzu_#{version}_universal.dmg"
  name "Kudzu"
  desc "Fast, keyboard-first text expander"
  homepage "https://github.com/Stringsaeed/kudzu"

  livecheck do
    url :url
    strategy :github_latest
  end

  # Kudzu updates itself; Homebrew shouldn't fight it.
  auto_updates true
  depends_on macos: ">= :sonoma"

  app "Kudzu.app"

  uninstall quit: "sh.saeed.kudzu"

  zap trash: [
    "~/Library/Application Support/sh.saeed.kudzu",
    "~/Library/Caches/sh.saeed.kudzu",
    "~/Library/LaunchAgents/Kudzu.plist",
    "~/Library/Preferences/sh.saeed.kudzu.plist",
    "~/Library/Saved Application State/sh.saeed.kudzu.savedState",
  ]
end
CASK
echo "wrote $TAP/Casks/kudzu.rb ($VERSION)"
